 "content": "from collections import Counter


def transform(grid):
    """Move all non-background cells down by one row, clipping at the edge."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background and r + 1 < h:
                out[r + 1][c] = value
    return out
